import os
import torch

"""
If you are working with deep learning models, PyTorch 2.x can automatically generate and optimize GPU code from your standard Python functions using its TorchInductor backend. It translates your Python logic into Triton code (NVIDIA's open-source language that compiles directly into high-performance CUDA binaries).
To physically generate and view the code, you can use the TORCH_LOGS environment variable:

"""


# Force PyTorch to print out the autogenerated GPU code
os.environ["TORCH_LOGS"] = "output_code"

# Standard Python/PyTorch function
@torch.compile
def heavy_math(x, y):
    return torch.sin(x) * torch.cos(y) + 2.0

# Run a dummy forward pass to trigger the code generation
a = torch.randn(1024, device="cuda")
b = torch.randn(1024, device="cuda")
out = heavy_math(a, b)

